import{_ as a,c as o,o as t,ae as i}from"./chunks/framework.ixH79I-5.js";const m=JSON.parse('{"title":"v1.1.1 Changelog","description":"Changelog","frontmatter":{"title":"v1.1.1 Changelog","description":"Changelog"},"headers":[],"relativePath":"changelog/1_1_1.md","filePath":"changelog/1_1_1.md"}'),l={name:"changelog/1_1_1.md"};function n(s,e,r,h,g,d){return t(),o("div",null,e[0]||(e[0]=[i('<h1 id="v1-1-1-changelog" tabindex="-1">v1.1.1 Changelog <a class="header-anchor" href="#v1-1-1-changelog" aria-label="Permalink to &quot;v1.1.1 Changelog&quot;">​</a></h1><p>v1.1.1 Released! New feature, small changes and a couple bug patches. Visual Theme Editor may be referred to as VTE.</p><h3 id="new-features" tabindex="-1"><strong>New Features</strong> <a class="header-anchor" href="#new-features" aria-label="Permalink to &quot;**New Features**&quot;">​</a></h3><ul><li>Ability to Import/Export Custom Themes, as a .BKT file (VTE only) or a .CSS file (global)</li></ul><h3 id="new-themes" tabindex="-1"><strong>New Themes</strong> <a class="header-anchor" href="#new-themes" aria-label="Permalink to &quot;**New Themes**&quot;">​</a></h3><ul><li>Minecraft Theme - Convy32</li><li>Ocean Theme - Solar</li></ul><h3 id="changes" tabindex="-1"><strong>Changes</strong> <a class="header-anchor" href="#changes" aria-label="Permalink to &quot;**Changes**&quot;">​</a></h3><ul><li>Added Surveys &amp; Notes to Dynamic Navbar</li><li>Add link text colour &amp; more border colour options (VTE)</li><li>Refreshed some layouts (e.g. Custom tab) in the Settings page (and buttons too!)</li><li>Rearranged order of themes to push new ones higher up</li><li>VTT now tells you if a background image is too small (pixelation warning)</li></ul><h3 id="fixes" tabindex="-1"><strong>Fixes</strong> <a class="header-anchor" href="#fixes" aria-label="Permalink to &quot;**Fixes**&quot;">​</a></h3><ul><li>Firefox support is back!</li><li>VTE Background Images now stay after re-editing theme</li><li>Swiping left to unpin no longer deletes the notice</li><li>Fix profile images not loading on custom theme (patch), single user issue so hoping this works</li><li>Stop infinite loader on RSS page by not loading modules while on select page</li></ul><h3 id="development-notes" tabindex="-1"><strong>Development Notes</strong> <a class="header-anchor" href="#development-notes" aria-label="Permalink to &quot;**Development Notes**&quot;">​</a></h3><ul><li>Custom Page API has now been completed (mostly)</li><li>Compiled CSS from VTT now shows comments with what it generated</li></ul><p>You can view more notes and the list of commits in the GitHub release. Big thanks to our <a href="https://discord.gg/HjJvakyAXe" target="_blank" rel="noreferrer">Discord community</a> for reporting bugs and giving us suggestions.</p>',13)]))}const c=a(l,[["render",n]]);export{m as __pageData,c as default};
